SELECT DISTINCT ?item ?matchedLabel ?en ?zh ?description ?kind WHERE {
          VALUES ?matchedLabel { "Bernoulli's principle"@en "Doppler effect"@en "Gibbs free energy"@en "Helmholtz free energy"@en "Hooke's law"@en "Navier-Stokes equations"@en "Reynolds number"@en "acoustic impedance"@en "adiabatic process"@en "amplitude"@en "angular frequency"@en "bernoulli's principle"@en "blackbody radiation"@en "buoyancy"@en "coefficient of restitution"@en "constructive interference"@en "continuity equation"@en "convection"@en "damped oscillation"@en "damping"@en "density"@en "destructive interference"@en "diffraction"@en "dispersion"@en "doppler effect"@en "enthalpy"@en "entropy"@en "first law of thermodynamics"@en "fluid dynamics"@en "forced oscillation"@en "free energy"@en "frequency"@en "gibbs free energy"@en "group velocity"@en "harmonic oscillator"@en "heat"@en "heat capacity"@en "heat conduction"@en "helmholtz free energy"@en "hooke's law"@en "intensity"@en "interference"@en "internal energy"@en "isobaric process"@en "isochoric process"@en "isothermal process"@en "laminar flow"@en "longitudinal wave"@en "navier-stokes equations"@en "oscillation"@en "pendulum"@en "period"@en "phase"@en "phase difference"@en "phase velocity"@en "pressure"@en "resonance"@en "reversible process"@en "reynolds number"@en "second law of thermodynamics"@en "simple harmonic motion"@en "simple pendulum"@en "sound wave"@en "specific heat capacity"@en "spring constant"@en "standing wave"@en "superposition"@en "surface tension"@en "temperature"@en "thermal conductivity"@en "thermal energy"@en "thermal equilibrium"@en "thermal expansion"@en "thermal radiation"@en "thermodynamics"@en "third law of thermodynamics"@en "transverse wave"@en "traveling wave"@en "turbulence"@en "viscosity"@en "wave"@en "wave equation"@en "wave number"@en "wave speed"@en "wavefront"@en "wavelength"@en "zeroth law of thermodynamics"@en }
          ?item (rdfs:label|skos:altLabel) ?matchedLabel.
          OPTIONAL { ?item rdfs:label ?en. FILTER(LANG(?en)="en") }
          OPTIONAL { ?item rdfs:label ?zh. FILTER(LANG(?zh) IN ("zh-hans","zh-cn","zh")) }
          OPTIONAL { ?item schema:description ?description. FILTER(LANG(?description)="en") }
          OPTIONAL { ?item wdt:P31 ?kind }
        }
